// Prepared renderer scenarios. The parent runner owns browser launch and teardown.
export default async function dataMcpScenarios(review) {
  await review.waitFor('window.__modelReview?.ready === true');
  await review.viewport(1440, 1000);
  await review.evaluate(`(() => {
    const fixture=window.__modelReview,bridge=window.piDesktop,clone=value=>structuredClone(value),cwd=fixture.snapshot.cwd;
    const machine={rows:[{path:cwd+'/sessions/current.jsonl',id:'current',name:'当前会话',firstMessage:'当前会话',modified:'2026-10-09T08:00:00Z',messageCount:12,cwd,registered:true,running:false,bytes:4096,pinned:true},{path:cwd+'/sessions/other.jsonl',id:'other',name:'其他工作区会话',firstMessage:'其他工作区会话',modified:'2026-10-08T08:00:00Z',messageCount:3,cwd:'E:/elsewhere/project',registered:false,running:false,bytes:2048,archived:true}]};
    const state={calls:[],machine,mcp:{cwd,sessionId:fixture.snapshot.sessionId,projectTrusted:true,servers:[{id:'review-mcp',scope:'user',name:'本地审查工具',enabled:true,transport:'stdio',command:'node',args:['fixture.mjs'],requestTimeoutMs:30000,status:'disconnected',tools:[]}]}};
    bridge.listMachineSessions=async()=>clone(state.machine.rows);
    bridge.updateSessionMeta=async(path,patch)=>{state.calls.push(['meta',path,clone(patch)]);const row=state.machine.rows.find(item=>item.path===path);if(row)Object.assign(row,patch);};
    bridge.deleteSession=async path=>{state.calls.push(['delete',path]);state.machine.rows=state.machine.rows.filter(item=>item.path!==path);};
    bridge.getMcpSnapshot=async()=>clone(state.mcp);
    bridge.connectMcpServer=async request=>{state.calls.push(['connect',clone(request)]);state.mcp.servers[0].status='connected';state.mcp.servers[0].tools=[{name:'echo',registeredName:'mcp_review_echo',description:'审查工具说明'}];return clone(state.mcp);};
    bridge.disconnectMcpServer=async request=>{state.calls.push(['disconnect',clone(request)]);state.mcp.servers[0].status='disconnected';state.mcp.servers[0].tools=[];return clone(state.mcp);};
    bridge.testMcpServer=async request=>{state.calls.push(['test',clone(request)]);return {tools:[{name:'echo'}],elapsedMs:18};};
    bridge.saveMcpServer=async request=>{state.calls.push(['saveMcp',clone(request)]);const row={...request.config,scope:request.scope,status:'disconnected',tools:[]};const index=state.mcp.servers.findIndex(item=>item.id===row.id);if(index<0)state.mcp.servers.push(row);else state.mcp.servers[index]=row;return clone(state.mcp);};
    bridge.removeMcpServer=async request=>{state.calls.push(['removeMcp',clone(request)]);state.mcp.servers=state.mcp.servers.filter(item=>item.id!==request.id);return clone(state.mcp);};
    window.__dataMcpReview=state;
  })()`);
  await review.click('.pd-settings-entry');
  await review.clickText('.pd-settings-nav button', '会话管理');
  await review.waitFor("document.querySelector('.pd-session-management')?.textContent.includes('其他工作区会话')");
  await review.assert("document.querySelector('.pd-session-management').textContent.includes('未打开的工作区')", 'Machine-wide sessions mark unregistered workspaces');
  await review.screenshot('data-mcp-01-session-management');
  await review.assert("Boolean(document.querySelector('.pd-session-management-row[data-session-path$=\"other.jsonl\"]'))", 'Rows expose management actions');
  await review.evaluate(`(() => { const row = document.querySelector('.pd-session-management-row[data-session-path$="other.jsonl"]'); const button = [...row.querySelectorAll('button')].find(item => item.textContent === '取消归档'); button.click(); })()`);
  await review.waitFor("window.__dataMcpReview.calls.some(call=>call[0]==='meta')");
  await review.assert("window.__dataMcpReview.calls.find(call=>call[0]==='meta')[2].archived===false", 'Unarchive toggles the machine-wide row');
  await review.clickText('.pd-settings-nav button', 'MCP');
  await review.waitFor("Boolean(document.querySelector('.pd-mcp-server'))");
  await review.assert("!window.__dataMcpReview.calls.some(call=>call[0]==='connect')", 'Opening MCP settings does not launch a server');
  await review.clickText('.pd-mcp-server button', '测试连接');
  await review.waitFor("document.querySelector('.pd-mcp-notice')?.textContent.includes('测试连接已关闭')");
  await review.assert("!document.querySelector('.pd-mcp-server details')", 'A test connection does not register tools');
  await review.clickText('.pd-mcp-server button', '连接到当前会话');
  await review.waitFor("document.querySelector('.pd-mcp-status')?.textContent==='已连接'");
  await review.click('.pd-mcp-server summary');
  await review.assert("document.querySelector('.pd-mcp-server details').textContent.includes('mcp_review_echo')", 'Connected tool identities are inspectable');
  await review.screenshot('data-mcp-02-connected');
  await review.clickText('.pd-mcp-server button', '断开');
  await review.waitFor("document.querySelector('.pd-mcp-status')?.textContent==='未连接'");
  await review.assert("!document.querySelector('.pd-mcp-server details')", 'Disconnect removes tool availability from the panel');
  await review.clickText('.pd-mcp-toolbar button', '添加服务器');
  await review.waitFor("Boolean(document.querySelector('.pd-mcp-editor[open] .pd-mcp-form'))");
  await review.screenshot('data-mcp-03-form');
  await review.viewport(680, 900);
  await review.screenshot('data-mcp-04-narrow-form');
  await review.assert("document.querySelector('.pd-mcp-panel').scrollWidth<=document.querySelector('.pd-mcp-panel').clientWidth+1", 'MCP form fits the narrow settings panel');
  await review.assert("(() => { const box = document.querySelector('.pd-mcp-editor').getBoundingClientRect(); return box.left >= 0 && box.right <= innerWidth; })()", 'MCP editor dialog fits a narrow window');
  await review.key('Escape');
  await review.waitFor("!document.querySelector('.pd-mcp-editor[open]')");
  await review.viewport(1440, 1000);
  await review.clickText('.pd-mcp-server button', '移除');
  await review.waitFor("Boolean(document.querySelector('.pd-mcp-remove[open]'))");
  await review.screenshot('data-mcp-05-remove');
  await review.clickText('.pd-mcp-remove button', '确认移除');
  await review.waitFor("Boolean(document.querySelector('.pd-mcp-empty'))");
  await review.assert("window.__dataMcpReview.calls.some(call=>call[0]==='removeMcp')", 'Confirming removal removes the server');
  await review.clickText('.pd-settings-nav button', '外观');
  await review.clickText('.pd-appearance-choice', '浅色');
  await review.clickText('.pd-settings-nav button', 'MCP');
  await review.waitFor("Boolean(document.querySelector('.pd-mcp-empty'))");
  await review.screenshot('data-mcp-06-light-empty');
}
